"""Virtual address space auditing for the wvas diagnostic collector.

The collector asks three questions about a target process:

``regions(pid)``
    Which parts of the virtual address space does the process have in use?

``file_backed_regions(pid)``
    Which of those parts are backed by a file on disk, and which file?

``modules(pid)``
    Which executable images are loaded, and where?

The answers are what the field engineers read when a machine reports
"something keeps the log file mapped" or "the process has no address space
left", so they have to describe the target process, not a snapshot of an
earlier call.

Two properties matter for every number that leaves this module:

* addresses and lengths are reported at the full width the system reports
  them at, so a report can be compared against a debugger one line at a time;
* a ``path`` is either a form the caller can hand to ``open()`` (a drive
  letter path or a UNC path) or ``None``.
"""

import ctypes
import os

from . import _winapi as w
from .errors import WVasError

#: Win32 paths can reach ~32k characters, so the query buffers start large
#: enough for anything the file system can hand back and still grow on demand.
PATH_BUFFER_CHARS = 32768

_PROTECTION_NAMES = {
    w.PAGE_NOACCESS: "none",
    w.PAGE_READONLY: "r",
    w.PAGE_READWRITE: "rw",
    w.PAGE_WRITECOPY: "wc",
    w.PAGE_EXECUTE: "x",
    w.PAGE_EXECUTE_READ: "xr",
    w.PAGE_EXECUTE_READWRITE: "xrw",
    w.PAGE_EXECUTE_WRITECOPY: "xwc",
}

_TYPE_NAMES = {
    w.MEM_IMAGE: "image",
    w.MEM_MAPPED: "mapped",
    w.MEM_PRIVATE: "private",
}

#: NT device prefixes used by the network redirectors. A name below one of
#: these is a UNC path with the prefix swapped for ``\\``.
_NETWORK_DEVICE_PREFIXES = (
    "\\Device\\Mup\\",
    "\\Device\\LanmanRedirector\\",
    "\\Device\\WinDfs\\Root\\",
    "\\Device\\WinDfs\\",
)


def protection_name(protect):
    """Map a PAGE_* protection value onto its short textual name.

    Pure: modifier bits (``PAGE_GUARD``, ``PAGE_NOCACHE``,
    ``PAGE_WRITECOMBINE``) are ignored and nothing is queried.
    """
    try:
        value = int(protect)
    except (TypeError, ValueError):
        return "?"
    return _PROTECTION_NAMES.get(value & 0xFF, "?")


def type_name(region_type):
    """Map a MEM_* region type onto its short textual name. Pure."""
    try:
        value = int(region_type)
    except (TypeError, ValueError):
        return "private"
    return _TYPE_NAMES.get(value, "private")


# ---------------------------------------------------------------------------
# platform plumbing
# ---------------------------------------------------------------------------


def _require_platform(pid=None):
    if not w.AVAILABLE:
        raise WVasError(
            "virtual address space auditing is only supported on Windows",
            kind="unsupported",
            pid=pid,
        )


def _check_pid(pid):
    if isinstance(pid, bool) or not isinstance(pid, int) or pid <= 0:
        raise WVasError("pid must be a positive integer", kind="badarg", pid=pid)


def _open_error(code, pid):
    """Classify a failed ``OpenProcess``."""
    if code == w.ERROR_ACCESS_DENIED:
        return WVasError(
            "access denied opening process", kind="access-denied", pid=pid
        )
    if code in (w.ERROR_INVALID_PARAMETER, w.ERROR_FILE_NOT_FOUND):
        return WVasError("no such process", kind="no-such-process", pid=pid)
    return WVasError(
        "OpenProcess failed with error %d" % (code,), kind="query-failed", pid=pid
    )


#: Access masks tried in turn. The first one allows ``GetMappedFileNameW``;
#: the weaker ones still allow ``VirtualQueryEx`` on protected processes.
_ACCESS_MASKS = (
    w.PROCESS_QUERY_INFORMATION | w.PROCESS_VM_READ,
    w.PROCESS_QUERY_LIMITED_INFORMATION | w.PROCESS_VM_READ,
    w.PROCESS_QUERY_INFORMATION,
    w.PROCESS_QUERY_LIMITED_INFORMATION,
)


def _open_process(pid):
    """Open ``pid`` for reading, or raise a classified :class:`WVasError`."""
    _check_pid(pid)
    _require_platform(pid)

    first_error = 0
    for mask in _ACCESS_MASKS:
        ctypes.set_last_error(0)
        handle = w.OpenProcess(mask, False, pid)
        if handle:
            return handle
        code = w.last_error()
        if not first_error:
            first_error = code
        if code not in (w.ERROR_ACCESS_DENIED,):
            # Anything other than "not enough rights" will not get better
            # with a weaker mask.
            break
    raise _open_error(first_error, pid)


def _max_address():
    """Highest address the scan has to walk up to."""
    info = w.SYSTEM_INFO()
    w.GetSystemInfo(ctypes.byref(info))
    top = int(info.lpMaximumApplicationAddress)
    if top <= 0:
        top = (1 << (8 * ctypes.sizeof(ctypes.c_void_p))) - 1
    return top


# ---------------------------------------------------------------------------
# NT device path -> path the caller can open
# ---------------------------------------------------------------------------


def _drive_map():
    """Map NT device names onto DOS drive roots, e.g. ``\\Device\\...`` -> ``C:``."""
    mapping = []
    buffer = ctypes.create_unicode_buffer(512)
    length = w.GetLogicalDriveStringsW(len(buffer), buffer)
    if length and length < len(buffer):
        roots = [item for item in buffer[:length].split("\x00") if item]
    else:
        roots = ["%s:\\" % chr(letter) for letter in range(ord("A"), ord("Z") + 1)]

    target = ctypes.create_unicode_buffer(PATH_BUFFER_CHARS)
    for root in roots:
        letter = root[:2]
        if len(letter) != 2 or letter[1] != ":":
            continue
        written = w.QueryDosDeviceW(letter, target, len(target))
        if not written:
            continue
        for device in target[: max(written - 1, 0)].split("\x00"):
            if device:
                mapping.append((device, letter))
    # Longest device name first: \Device\HarddiskVolume1 must not shadow
    # \Device\HarddiskVolume10.
    mapping.sort(key=lambda item: len(item[0]), reverse=True)
    return mapping


def _strip_nt_prefix(path):
    """Drop the ``\\??\\``, ``\\\\?\\`` and ``\\\\.\\`` escape prefixes."""
    for prefix in ("\\??\\UNC\\", "\\\\?\\UNC\\", "\\\\.\\UNC\\"):
        if path.startswith(prefix):
            return "\\\\" + path[len(prefix):]
    for prefix in ("\\??\\", "\\\\?\\", "\\\\.\\"):
        if path.startswith(prefix):
            return path[len(prefix):]
    return path


def _looks_openable(path):
    """True when ``path`` is a drive letter path or a UNC path."""
    if not path:
        return False
    if path.startswith("\\\\"):
        # UNC, but not one of the escape namespaces.
        rest = path[2:]
        if rest.startswith("?\\") or rest.startswith(".\\"):
            return False
        return "\\" in rest.rstrip("\\") or bool(rest)
    if len(path) >= 3 and path[1] == ":" and path[2] == "\\" and path[0].isalpha():
        return True
    return False


def _dos_path(native_path, drive_map=None):
    """Translate an NT path into a path the caller can open, or ``None``.

    Handles ``\\Device\\HarddiskVolumeN\\...`` (via the drive letter table),
    the network redirector devices (translated into UNC form) and the
    ``\\??\\`` style escapes. Anything that cannot be turned into a drive
    letter or UNC path yields ``None``.
    """
    if not native_path:
        return None

    path = _strip_nt_prefix(native_path)
    if _looks_openable(path):
        return path

    for prefix in _NETWORK_DEVICE_PREFIXES:
        if path.lower().startswith(prefix.lower()):
            remainder = path[len(prefix):]
            if not remainder:
                return None
            return "\\\\" + remainder

    if drive_map is None:
        drive_map = _drive_map()
    lowered = path.lower()
    for device, letter in drive_map:
        device_lower = device.lower()
        if lowered == device_lower:
            return letter + "\\"
        if lowered.startswith(device_lower + "\\"):
            candidate = letter + path[len(device):]
            return candidate if _looks_openable(candidate) else None

    return None


def _mapped_path(handle, address, drive_map):
    """Return an openable path for the file backing ``address``, or ``None``.

    ``GetMappedFileNameW`` fails for memory that no file backs (private
    memory, reserved ranges and anonymous section objects created from
    ``INVALID_HANDLE_VALUE``), which is reported as ``None`` rather than an
    empty name.
    """
    size = PATH_BUFFER_CHARS
    for _ in range(2):
        buffer = ctypes.create_unicode_buffer(size)
        ctypes.set_last_error(0)
        written = w.GetMappedFileNameW(
            handle, ctypes.c_void_p(address), buffer, size
        )
        if written:
            if written >= size - 1 and size < 1 << 20:
                size *= 2
                continue
            return _dos_path(buffer.value, drive_map)
        if w.last_error() == w.ERROR_INSUFFICIENT_BUFFER and size < 1 << 20:
            size *= 2
            continue
        return None
    return None


# ---------------------------------------------------------------------------
# region scan
# ---------------------------------------------------------------------------


def _scan(handle, pid, include_reserved, drive_map):
    """Walk the whole address space of ``handle`` with ``VirtualQueryEx``."""
    wanted = (w.MEM_COMMIT, w.MEM_RESERVE) if include_reserved else (w.MEM_COMMIT,)
    result = []
    mbi = w.MEMORY_BASIC_INFORMATION()
    mbi_size = ctypes.sizeof(mbi)
    max_address = _max_address()
    address = 0
    first = True

    while address <= max_address:
        ctypes.set_last_error(0)
        written = w.VirtualQueryEx(
            handle, ctypes.c_void_p(address), ctypes.byref(mbi), mbi_size
        )
        if not written:
            code = w.last_error()
            if first:
                if code == w.ERROR_ACCESS_DENIED:
                    raise WVasError(
                        "access denied querying process",
                        kind="access-denied",
                        pid=pid,
                    )
                if code in (w.ERROR_INVALID_HANDLE, w.ERROR_INVALID_PARAMETER):
                    raise WVasError(
                        "no such process", kind="no-such-process", pid=pid
                    )
                raise WVasError(
                    "VirtualQueryEx failed with error %d" % (code,),
                    kind="query-failed",
                    pid=pid,
                )
            # A 32 bit target simply runs out of address space before the
            # host's maximum application address is reached.
            break
        first = False

        base = int(mbi.BaseAddress)
        size = int(mbi.RegionSize)
        state = int(mbi.State)

        if state in wanted and size > 0:
            region_type = int(mbi.Type)
            path = None
            if region_type in (w.MEM_IMAGE, w.MEM_MAPPED):
                path = _mapped_path(handle, base, drive_map)
            result.append({
                "base": base,
                "size": size,
                "state": "commit" if state == w.MEM_COMMIT else "reserve",
                "type": type_name(region_type),
                "protect": protection_name(mbi.Protect),
                "path": path,
                "image": region_type == w.MEM_IMAGE,
                "_allocation_base": int(mbi.AllocationBase) or base,
            })

        if size <= 0:
            break
        next_address = base + size
        if next_address <= address:
            break
        address = next_address

    result.sort(key=lambda item: item["base"])
    return result


def regions(pid, include_reserved=True):
    """Return the regions of ``pid``'s virtual address space.

    The list is ascending by ``base`` and holds committed regions plus, when
    ``include_reserved`` is true, reserved-but-uncommitted ones.
    """
    handle = _open_process(pid)
    try:
        drive_map = _drive_map()
        scanned = _scan(handle, pid, bool(include_reserved), drive_map)
    finally:
        w.CloseHandle(handle)
    for item in scanned:
        item.pop("_allocation_base", None)
    return scanned


def file_backed_regions(pid):
    """Return only the regions that have a file behind them."""
    return [item for item in regions(pid) if item["path"] is not None]


# ---------------------------------------------------------------------------
# modules
# ---------------------------------------------------------------------------


def _enumerated_modules(handle, drive_map):
    """Images reported by the loader, keyed by base address.

    Returns ``{base: path_or_None}``. An empty dict means the loader could not
    be asked (the image list is then rebuilt from the region scan).
    """
    if w.EnumProcessModulesEx is None:
        return {}

    count = 256
    for _ in range(6):
        array = (ctypes.c_size_t * count)()
        needed = ctypes.wintypes.DWORD(0)
        ctypes.set_last_error(0)
        ok = w.EnumProcessModulesEx(
            handle,
            array,
            ctypes.sizeof(array),
            ctypes.byref(needed),
            w.LIST_MODULES_ALL,
        )
        if not ok:
            return {}
        entries = needed.value // ctypes.sizeof(ctypes.c_size_t)
        if entries > count:
            count = entries + 64
            continue
        found = {}
        for index in range(entries):
            base = int(array[index])
            if base:
                found[base] = _module_path(handle, base, drive_map)
        return found
    return {}


def _module_path(handle, base, drive_map):
    """Best openable path for the image loaded at ``base``, or ``None``."""
    size = PATH_BUFFER_CHARS
    for _ in range(2):
        buffer = ctypes.create_unicode_buffer(size)
        ctypes.set_last_error(0)
        written = w.GetModuleFileNameExW(handle, base, buffer, size)
        if written:
            if written >= size - 1 and size < 1 << 20:
                size *= 2
                continue
            path = _dos_path(buffer.value, drive_map)
            if path is not None:
                return path
            break
        break
    # The loader could not name it (or named it in a form that cannot be
    # opened); fall back to the section object behind the mapping.
    return _mapped_path(handle, base, drive_map)


def _module_size(handle, base, fallback):
    info = w.MODULEINFO()
    ctypes.set_last_error(0)
    if w.GetModuleInformation(handle, base, ctypes.byref(info), ctypes.sizeof(info)):
        size = int(info.SizeOfImage)
        if size > 0:
            return size
    return fallback


def modules(pid):
    """Return the loaded executable images, lowest base address first.

    Every image appears exactly once and no file path is repeated. ``path`` is
    the image file's real on-disk path, or ``None`` when it cannot be turned
    into something the caller could open.
    """
    handle = _open_process(pid)
    try:
        drive_map = _drive_map()
        scanned = _scan(handle, pid, True, drive_map)
        loaded = _enumerated_modules(handle, drive_map)

        # Image allocations seen in the address space, with their full span.
        spans = {}
        for item in scanned:
            if not item["image"]:
                continue
            allocation = item["_allocation_base"]
            end = item["base"] + item["size"]
            known = spans.get(allocation)
            if known is None:
                spans[allocation] = [end, item["path"]]
            else:
                known[0] = max(known[0], end)
                if known[1] is None:
                    known[1] = item["path"]

        candidates = {}
        for base, path in loaded.items():
            span = spans.get(base)
            fallback = span[0] - base if span else 0
            if path is None and span is not None:
                path = span[1]
            candidates[base] = {
                "path": path,
                "base": base,
                "size": _module_size(handle, base, fallback),
            }
        # Images mapped without the loader naming them still belong in the
        # list; the address space is the authority on what is mapped.
        for base, (end, path) in spans.items():
            if base in candidates:
                continue
            candidates[base] = {
                "path": path if path is not None else _module_path(
                    handle, base, drive_map
                ),
                "base": base,
                "size": _module_size(handle, base, end - base),
            }
    finally:
        w.CloseHandle(handle)

    result = []
    seen_paths = set()
    for base in sorted(candidates):
        entry = candidates[base]
        path = entry["path"]
        if path is not None:
            key = os.path.normcase(path)
            if key in seen_paths:
                continue
            seen_paths.add(key)
        result.append(entry)
    return result

