    first_error = 0
    for mask in _ACCESS_MASKS:
        ctypes.set_last_error(0)
        handle = w.OpenProcess(mask, False, pid)
        if handle:
            return handle
        code = w.last_error()
        if not first_error:
            first_error = code
        if code != w.ERROR_ACCESS_DENIED:
            # Anything other than "not enough rights" will not improve with a
            # weaker mask.
            break
    raise _open_error(first_error, pid)


def _max_address():
    """Highest user mode address the scan has to walk up to."""
    info = w.SYSTEM_INFO()
    w.GetSystemInfo(ctypes.byref(info))
    top = int(info.lpMaximumApplicationAddress)
    if top <= 0:
        top = (1 << (8 * ctypes.sizeof(ctypes.c_void_p))) - 1
    return top


# ---------------------------------------------------------------------------
# NT device path -> a path the caller can open
# ---------------------------------------------------------------------------


def _drive_map():
    """NT device names paired with DOS drive roots, longest device first."""
    mapping = []
    buffer = ctypes.create_unicode_buffer(512)
    length = w.GetLogicalDriveStringsW(len(buffer), buffer)
    if length and length < len(buffer):
        roots = [item for item in buffer[:length].split("\x00") if item]
    else:
        roots = ["%s:\\" % chr(letter) for letter in range(ord("A"), ord("Z") + 1)]

    target = ctypes.create_unicode_buffer(PATH_BUFFER_CHARS)
    for root in roots:
        letter = root[:2]
        if len(letter) != 2 or letter[1] != ":":
            continue
        if w.QueryDosDeviceW(letter, target, len(target)):
            for device in target[:].split("\x00"):
                if device:
                    mapping.append((device, letter))
                else:
                    break
    # \Device\HarddiskVolume1 must not shadow \Device\HarddiskVolume10.
    mapping.sort(key=lambda item: len(item[0]), reverse=True)
    return mapping


def _strip_nt_prefix(path):
    """Drop the ``\\??\\``, ``\\\\?\\`` and ``\\\\.\\`` escape prefixes."""
    for prefix in ("\\??\\UNC\\", "\\\\?\\UNC\\", "\\\\.\\UNC\\"):
        if path.startswith(prefix):
            return "\\\\" + path[len(prefix):]
    for prefix in ("\\??\\", "\\\\?\\", "\\\\.\\"):
        if path.startswith(prefix):
            return path[len(prefix):]
    return path


def _looks_openable(path):
    """True when ``path`` is a drive letter path or a plain UNC path."""
    if not path:
        return False
    if path.startswith("\\\\"):
        rest = path[2:]
        if not rest or rest.startswith("?\\") or rest.startswith(".\\"):
            return False
        return True
    return (
        len(path) >= 3
        and path[0].isalpha()
        and path[1] == ":"
        and path[2] == "\\"
    )


def _dos_path(native_path, drive_map=None):
    """Translate an NT path into something the caller can open, or ``None``.

    Understands ``\\Device\\HarddiskVolumeN\\...`` (through the drive letter
    table), the network redirector devices (turned into UNC paths) and the
    ``\\??\\`` style escapes. A name that cannot be expressed as a drive
    letter or UNC path yields ``None`` rather than an unusable string.
    """
    if not native_path:
        return None

    path = _strip_nt_prefix(native_path)
    if _looks_openable(path):
        return path

    lowered = path.lower()
    for prefix in _NETWORK_DEVICE_PREFIXES:
        if lowered.startswith(prefix.lower()):
            remainder = path[len(prefix):]
            if not remainder:
                return None
            candidate = "\\\\" + remainder
            return candidate if _looks_openable(candidate) else None

    if drive_map is None:
        drive_map = _drive_map()
    for device, letter in drive_map:
        device_lower = device.lower()
        if lowered == device_lower:
            candidate = letter + "\\"
        elif lowered.startswith(device_lower + "\\"):
            candidate = letter + path[len(device):]
        else:
            continue
        return candidate if _looks_openable(candidate) else None

    return None


def _mapped_path(handle, address, drive_map):
    """An openable path for the file backing ``address``, or ``None``.

    ``GetMappedFileNameW`` fails for memory no file backs: private memory,
    reserved ranges and anonymous sections created from
    ``INVALID_HANDLE_VALUE``. Those are reported as ``None``, never as an
    empty name.
    """
    size = PATH_BUFFER_CHARS
    while True:
        buffer = ctypes.create_unicode_buffer(size)
        ctypes.set_last_error(0)
        written = w.GetMappedFileNameW(
            handle, ctypes.c_void_p(address), buffer, size
        )
        if written:
            if written >= size - 1 and size < _MAX_PATH_BUFFER_CHARS:
                size *= 2
                continue
            return _dos_path(buffer.value, drive_map)
        if (
            w.last_error() == w.ERROR_INSUFFICIENT_BUFFER
            and size < _MAX_PATH_BUFFER_CHARS
        ):
            size *= 2
            continue
        return None


# ---------------------------------------------------------------------------
# region scan
# ---------------------------------------------------------------------------


def _scan(handle, pid, include_reserved, drive_map):
    """Walk the whole address space of ``handle`` with ``VirtualQueryEx``."""
    wanted = (w.MEM_COMMIT, w.MEM_RESERVE) if include_reserved else (w.MEM_COMMIT,)
    result = []
    mbi = w.MEMORY_BASIC_INFORMATION()
    mbi_size = ctypes.sizeof(mbi)
    max_address = _max_address()
    address = 0
    first = True

    while address <= max_address:
        ctypes.set_last_error(0)
        written = w.VirtualQueryEx(
            handle, ctypes.c_void_p(address), ctypes.byref(mbi), mbi_size
        )
        if not written:
            code = w.last_error()
            if first:
                raise _query_error(code, pid)
            # A 32 bit target runs out of address space well before the
            # host's maximum application address; that is not a failure.
            break
        first = False

        base = int(mbi.BaseAddress)
        size = int(mbi.RegionSize)
        state = int(mbi.State)

        if size <= 0:
            break

        if state in wanted:
            region_type = int(mbi.Type)
            path = None
            if region_type in (w.MEM_IMAGE, w.MEM_MAPPED):
                path = _mapped_path(handle, base, drive_map)
            result.append({
                "base": base,
                "size": size,
                "state": "commit" if state == w.MEM_COMMIT else "reserve",
                "type": type_name(region_type),
                "protect": protection_name(mbi.Protect),
                "path": path,
                "image": region_type == w.MEM_IMAGE,
                "_allocation_base": int(mbi.AllocationBase) or base,
            })

        next_address = base + size
        if next_address <= address:
            break
        address = next_address

    result.sort(key=lambda item: item["base"])
    return result


def _query_error(code, pid):
    if code == w.ERROR_ACCESS_DENIED:
        return WVasError(
            "access denied querying process", kind="access-denied", pid=pid
        )
    if code in (w.ERROR_INVALID_HANDLE, w.ERROR_INVALID_PARAMETER):
        return WVasError("no such process", kind="no-such-process", pid=pid)
    return WVasError(
        "VirtualQueryEx failed with error %d" % (code,),
        kind="query-failed",
        pid=pid,
    )


def regions(pid, include_reserved=True):
    """Return the regions of ``pid``'s virtual address space.

    Ascending by ``base``; committed regions always, plus the
    reserved-but-uncommitted ones when ``include_reserved`` is true.
    """
    handle = _open_process(pid)
    try:
        drive_map = _drive_map()
        scanned = _scan(handle, pid, bool(include_reserved), drive_map)
    finally:
        w.CloseHandle(handle)
    for item in scanned:
        del item["_allocation_base"]
    return scanned


def file_backed_regions(pid):
    """Return only the regions that have a file behind them."""
    return [item for item in regions(pid) if item["path"] is not None]


# ---------------------------------------------------------------------------
# modules
# ---------------------------------------------------------------------------


def _enumerated_module_bases(handle):
    """Base addresses the loader reports, or ``None`` when it cannot be asked."""
    if w.EnumProcessModulesEx is None:
        return None

    count = 512
    for _ in range(8):
        array = (ctypes.c_size_t * count)()
        needed = ctypes.c_ulong(0)
        ctypes.set_last_error(0)
        ok = w.EnumProcessModulesEx(
            handle,
            array,
            ctypes.sizeof(array),
            ctypes.byref(needed),
            w.LIST_MODULES_ALL,
        )
        if not ok:
            return None
        entries = needed.value // ctypes.sizeof(ctypes.c_size_t)
        if entries > count:
            count = entries + 128
            continue
        return [int(array[index]) for index in range(entries) if array[index]]
    return None


def _module_path(handle, base, drive_map):
    """The best openable path for the image at ``base``, or ``None``."""
    size = PATH_BUFFER_CHARS
    while True:
        buffer = ctypes.create_unicode_buffer(size)
        ctypes.set_last_error(0)
        written = w.GetModuleFileNameExW(handle, base, buffer, size)
        if not written:
            break
        if written >= size - 1 and size < _MAX_PATH_BUFFER_CHARS:
            size *= 2
            continue
        path = _dos_path(buffer.value, drive_map)
        if path is not None:
            return path
        break
    # The loader could not name it, or named it in a form that cannot be
    # opened: ask the section object behind the mapping instead.
    return _mapped_path(handle, base, drive_map)


def _module_size(handle, base, fallback):
    info = w.MODULEINFO()
    ctypes.set_last_error(0)
    if w.GetModuleInformation(handle, base, ctypes.byref(info), ctypes.sizeof(info)):
        size = int(info.SizeOfImage)
        if size > 0:
            return size
    return fallback


def modules(pid):
    """Return the loaded executable images, lowest base address first.

    Each image appears exactly once and no file path repeats. ``path`` is the
    image file's real on-disk path, or ``None`` when it cannot be turned into
    a form the caller could open.
    """
    handle = _open_process(pid)
    try:
        drive_map = _drive_map()
        scanned = _scan(handle, pid, True, drive_map)

        # Collapse the many sections of each image onto its allocation base.
        spans = {}
        for item in scanned:
            if not item["image"]:
                continue
            allocation = item["_allocation_base"]
            end = item["base"] + item["size"]
            known = spans.get(allocation)
            if known is None:
                spans[allocation] = [end, item["path"]]
            else:
                known[0] = max(known[0], end)
                if known[1] is None:
                    known[1] = item["path"]

        bases = set(spans)
        enumerated = _enumerated_module_bases(handle)
        if enumerated:
            # The loader may know of an image the scan could not attribute.
            bases.update(enumerated)

        candidates = []
        for base in sorted(bases):
            span = spans.get(base)
            path = span[1] if span is not None else None
            if path is None:
                path = _module_path(handle, base, drive_map)
            fallback = span[0] - base if span is not None else 0
            candidates.append({
                "path": path,
                "base": base,
                "size": _module_size(handle, base, fallback),
            })
    finally:
        w.CloseHandle(handle)

    result = []
    seen = set()
    for entry in candidates:
        path = entry["path"]
        if path is not None:
            key = os.path.normcase(path)
            if key in seen:
                continue
            seen.add(key)
        result.append(entry)
    return result

